const r="https://api.heygen.com/v1";async function l(o,n){const e=await fetch(`${r}/video-agents`,{method:"POST",headers:{"X-Api-Key":o,"Content-Type":"application/json"},body:JSON.stringify(n)});if(!e.ok){const t=await e.json().catch(()=>({message:"That video creation didn't go through."}));throw new Error(t.message||"That video creation didn't go through.")}return(await e.json()).data}async function h(o,n){const e=await fetch(`${r}/video-agents/${n}`,{method:"GET",headers:{"X-Api-Key":o,"Content-Type":"application/json"}});if(!e.ok){const t=await e.json().catch(()=>({message:"Couldn't check the video status."}));throw new Error(t.message||"Couldn't check the video status.")}return(await e.json()).data}async function c(o,n){const e=await fetch(`${r}/videos/${n}`,{method:"GET",headers:{"X-Api-Key":o,"Content-Type":"application/json"}});if(!e.ok){const t=await e.json().catch(()=>({message:"Couldn't check the video status."}));throw new Error(t.message||"Couldn't check the video status.")}return(await e.json()).data}async function u(o,n,e=120,i=5e3){let t=null;for(let a=0;a<e;a++){const s=await h(o,n);if(s.status==="failed")throw new Error("That video generation ran into a problem.");if(s.video_id){t=s.video_id;break}if(s.status==="completed"&&!s.video_id)throw new Error("The video finished but something went wrong with the result.");await new Promise(d=>setTimeout(d,i))}if(!t)throw new Error("That video is taking longer than expected.");for(let a=0;a<e;a++){const s=await c(o,t);if(s.status==="completed")return s;if(s.status==="failed")throw new Error(s.failure_message||"Video generation failed");await new Promise(d=>setTimeout(d,i))}throw new Error("Timeout waiting for video completion")}async function w(o,n=10,e){let i=`${r}/videos?limit=${n}`;e&&(i+=`&token=${e}`);const t=await fetch(i,{method:"GET",headers:{"X-Api-Key":o}});if(!t.ok){const a=await t.json().catch(()=>({message:"Couldn't load the video list."}));throw new Error(a.message||"Couldn't load the video list.")}return t.json()}async function g(o,n){const e=await fetch(`${r}/videos/${n}`,{method:"DELETE",headers:{"X-Api-Key":o}});if(!e.ok){const t=await e.json().catch(()=>({message:"Couldn't delete that video."}));throw new Error(t.message||"Couldn't delete that video.")}return(await e.json()).data}export{l as heygenCreateVideoAgent,g as heygenDeleteVideo,w as heygenListVideos,h as heygenPollSession,c as heygenPollVideo,u as pollHeygenVideoAgent};
